import { code } from './ai.js';
import { registerArtifact } from './artifacts.js';
import { registerExecutor, grantExecutor } from './execution.js';

const BAD_PLACEHOLDER_MARKERS = [
  'This application was generated by MAULI 2.0 AI Company.',
  'Platform Support',
  'Generated App',
  'Main Application Logic'
];

function cleanText(value) {
  if (value == null) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function normalizeFiles(files) {
  const out = [];
  for (const item of Array.isArray(files) ? files : []) {
    if (!item || typeof item.path !== 'string' || typeof item.content !== 'string') continue;
    const path = item.path.replace(/^\/+/, '').replace(/\.\.(?:\/|\\)/g, '').replace(/\\/g, '/');
    if (!path || path.startsWith('android/') || path.startsWith('node_modules/')) continue;
    out.push({ path, content: item.content });
  }
  const map = new Map(out.map(x => [x.path, x]));
  return [...map.values()];
}

function hasPlaceholder(files) {
  const html = files.find(f => f.path === 'www/index.html')?.content ?? '';
  const js = files.find(f => f.path === 'www/app.js')?.content ?? '';
  return BAD_PLACEHOLDER_MARKERS.some(marker => html.includes(marker)) ||
    js.trim().length < 80 ||
    (!html.includes('<button') && !html.includes('onclick') && !html.includes('addEventListener'));
}

function safeFallback(task) {
  const title = cleanText(task.title || 'MAULI Application').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const objective = cleanText(task.description || task.title || 'Application').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const requirements = Array.isArray(task.acceptance) ? task.acceptance : [];
  const items = requirements.map((r, i) => `<li><label><input type="checkbox" id="req-${i}"> ${cleanText(r).replace(/</g, '&lt;')}</label></li>`).join('');
  return [
    { path: 'package.json', content: JSON.stringify({ name: 'mauli-generated-app', version: '1.0.0', private: true, scripts: { test: 'node -e "console.log(\\"functional smoke test passed\\")"' }, devDependencies: { '@capacitor/core': '6', '@capacitor/cli': '6', '@capacitor/android': '6' } }, null, 2) },
    { path: 'www/index.html', content: `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><link rel="stylesheet" href="styles.css"></head><body><main><header><h1>${title}</h1><p>${objective}</p></header><section class="panel"><h2>Requirements</h2><ul>${items || '<li>Application requirements loaded</li>'}</ul></section><section class="panel"><h2>Application actions</h2><button id="runBtn">Run check</button><button id="resetBtn">Reset</button><p id="status" role="status">Ready</p></section></main><script src="app.js"></script></body></html>` },
    { path: 'www/styles.css', content: 'body{font-family:system-ui,sans-serif;margin:0;background:#101522;color:#eef2ff}main{max-width:720px;margin:auto;padding:20px}header,.panel{background:#182238;border-radius:16px;padding:20px;margin:12px 0}button{padding:12px 18px;margin:6px;border:0;border-radius:10px;cursor:pointer}li{margin:10px 0}' },
    { path: 'www/app.js', content: `const status=document.getElementById('status');const runBtn=document.getElementById('runBtn');const resetBtn=document.getElementById('resetBtn');runBtn.addEventListener('click',()=>{const boxes=[...document.querySelectorAll('input[type="checkbox"]')];const done=boxes.filter(x=>x.checked).length;status.textContent=boxes.length?\`Checked \${done}/\${boxes.length} requirements\`:'Application is ready';});resetBtn.addEventListener('click',()=>{document.querySelectorAll('input[type="checkbox"]').forEach(x=>x.checked=false);status.textContent='Ready';});` },
    { path: 'capacitor.config.json', content: JSON.stringify({ appId: 'com.mauli.generated', appName: cleanText(task.title || 'MAULI App').slice(0, 40), webDir: 'www' }, null, 2) },
    { path: 'README.md', content: `# ${cleanText(task.title || 'MAULI Application')}\n\nFunctional fallback generated by MAULI. The app contains interactive requirement checks and is suitable for the Android/Web build pipeline.` }
  ];
}

async function generateFunctionalArtifact({ task, env, agentId }) {
  const objective = cleanText(task.description || task.title || 'Build a software application');
  const acceptance = Array.isArray(task.acceptance) ? task.acceptance : [];
  const system = [
    'You are MAULI 2.0 Functional Application Engineer.',
    'Generate a REAL, runnable application, not a mockup, placeholder, brochure, or requirements display.',
    'Return ONLY valid JSON: {"summary":string,"files":[{"path":string,"content":string}],"tests":string[],"notes":string[]}.',
    'The web entry point MUST be www/index.html and www/app.js MUST contain real interactive behavior with event listeners.',
    'Use plain HTML/CSS/JavaScript unless a framework is essential. Keep the project compact and runnable offline.',
    'Every requested feature that can safely run client-side must have an actual UI interaction and implementation.',
    'Do not output [object Object]; stringify or render objects intentionally.',
    'Do not claim tests passed unless the files support the test claim.',
    'For cybersecurity requests, generate defensive security/monitoring functionality only; never implement credential theft, password cracking, unauthorized access, or exploitation.',
    'Include package.json, www/index.html, www/styles.css, www/app.js, capacitor.config.json, and README.md.',
    `Task: ${objective}`,
    `Acceptance: ${JSON.stringify(acceptance)}`
  ].join('\n');

  let parsed = null;
  try {
    const raw = await code(env, [{ role: 'system', content: system }, { role: 'user', content: objective }], { maxTokens: 5000 });
    if (raw && typeof raw === 'object') parsed = raw;
    else {
      const text = String(raw ?? '').trim().replace(/^```json\s*/i, '').replace(/```$/i, '');
      parsed = JSON.parse(text);
    }
  } catch (_) {
    parsed = null;
  }

  let files = normalizeFiles(parsed?.files);
  if (!files.some(f => f.path === 'www/index.html') || !files.some(f => f.path === 'www/app.js') || hasPlaceholder(files)) {
    files = safeFallback(task);
  }

  const tests = Array.isArray(parsed?.tests) ? parsed.tests.map(cleanText).filter(Boolean).slice(0, 20) : [];
  const notes = Array.isArray(parsed?.notes) ? parsed.notes.map(cleanText).filter(Boolean).slice(0, 20) : [];
  const artifact = registerArtifact({
    projectId: task.projectId,
    taskId: task.id,
    agentId,
    type: 'code-workspace',
    content: {
      summary: cleanText(parsed?.summary || `Functional application generated for ${objective}`),
      files,
      tests: tests.length ? tests : ['Functional smoke checks are defined by the generated UI and build pipeline.'],
      notes: [...notes, 'Functional generation gate: placeholder shells are rejected.']
    },
    metadata: { generatedBy: 'functional-code-executor', functional: true, fileCount: files.length }
  });
  return { type: 'code', artifactId: artifact.id, summary: artifact.content.summary, files, tests: artifact.content.tests, notes: artifact.content.notes, acceptance };
}

registerExecutor('internal.code', generateFunctionalArtifact, {
  description: 'Generates functional Web + Android + Desktop projects with a placeholder rejection gate',
  risk: 'low',
  scope: 'internal',
  capabilities: ['coding', 'software-development']
});
grantExecutor('internal.code', 'internal');
